// x,y,z - центр, w,h,l - размеры (X,Y,Z); f: 1 = магазин (двигается при перезарядке), 2 = клинок (красится скином как основной цвет)
// rx - наклон вокруг оси X в градусах (+ = нижний конец уходит назад, - = задний конец опускается), rz - поворот вокруг оси Z (гранёные стволы, кольца, рога гарды)
// k - форма: 0 = коробка, 1 = цилиндр вдоль Z (w,h - диаметры, l - длина), 2 = цилиндр вдоль Y (w,l - диаметры, h - длина),
// 3 = цилиндр вдоль X (h,l - диаметры, w - длина), 4 = трапециевидная пластина (профиль в плоскости Y-Z, толщина w).
// a - у цилиндров: во сколько раз сужается торец со стороны +оси (0 = не сужается); у пластины: высота спереди (0 = как h)
// b - у пластины: смещение центра передней кромки по Y относительно задней
struct Part { float x, y, z, w, h, l; uint8_t c, f; float rx, rz; uint8_t k; float a, b; };
struct ModelDef { const Part* p; int n; Vector3 grip, fore; };

