static int gSkin[NUM_VIS] = {};     // выбранный скин для каждого оружия (0 = стандартный)

static const char* VisName(int i) { return i >= W_KNIFE ? KNIFE_NAMES[i - W_KNIFE] : WDEF[i].name; }
static const char* SkinName(int w, int sk) { return SKINS[w][(sk > 0 && sk < NUM_SKINS) ? sk : 0].name; }
// имя оружия вместе со скином: "AK-47 (Redline)"
static const char* WName(int w) {
    return gSkin[w] > 0 ? TextFormat("%s (%s)", WDEF[w].name, SKINS[w][gSkin[w]].name) : WDEF[w].name;
}

static void SkinsSave() {
    char buf[256];
    int n = snprintf(buf, sizeof(buf), "SSSKIN 1 %d", (int)NUM_VIS);
    for (int i = 0; i < NUM_VIS && n > 0 && n < (int)sizeof(buf) - 16; i++) n += snprintf(buf + n, sizeof(buf) - n, " %d", gSkin[i]);
    if (n > 0 && n < (int)sizeof(buf) - 8) snprintf(buf + n, sizeof(buf) - n, " K %d", gKnifeSel - W_KNIFE);
    SaveFileText("sandstrike_skins.cfg", buf);
}
static void SkinsLoad() {
    char* t = LoadFileText("sandstrike_skins.cfg");
    if (!t) return;
    int ver = 0, cnt = 0, off = 0;
    if (sscanf(t, "SSSKIN %d %d%n", &ver, &cnt, &off) == 2 && ver == 1 && cnt > 0 && cnt <= NUM_VIS) {
        int tmp[NUM_VIS] = {}; const char* p = t + off; bool ok = true;
        for (int i = 0; i < cnt; i++) {        // старые сохранения (без ножа) тоже читаются
            int v, o2 = 0;
            if (sscanf(p, " %d%n", &v, &o2) != 1) { ok = false; break; }
            p += o2;
            tmp[i] = (v >= 0 && v < NUM_SKINS) ? v : 0;
        }
        if (ok) {
            for (int i = 0; i < NUM_VIS; i++) gSkin[i] = tmp[i];
            int kv = 0, o3 = 0;
            if (sscanf(p, " K %d%n", &kv, &o3) == 1 && kv >= 0 && kv < NUM_VIS - W_KNIFE) gKnifeSel = W_KNIFE + kv;
        }
    }
    UnloadFileText(t);
}

// =====================================================================
//  ИНВЕНТАРЬ, ВАЛЮТЫ, КЕЙСЫ И БОКСЫ
//  Две валюты: GOLD (редкая, за неё кейсы) и SILVER (обычная, за неё боксы).
//  Скины платные: получить можно только из кейса / бокса. У каждого скина своя редкость.
//  Стандартный вид (скин 0) есть всегда. Сохранение: sandstrike_inv.cfg.
// =====================================================================
enum { R_COMMON, R_RARE, R_EPIC, R_LEGEND, NUM_RAR };
static const char* RAR_NAME[NUM_RAR] = { "COMMON", "RARE", "EPIC", "LEGENDARY" };
static const Color RAR_COL[NUM_RAR] = { { 170, 176, 190, 255 }, { 70, 150, 255, 255 }, { 175, 95, 255, 255 }, { 255, 170, 40, 255 } };
static const int RAR_SELL[NUM_RAR] = { 100, 400, 1200, 3500 };   // цена продажи (и компенсация за дубликат) в серебре

static int SkinPattern(int w, int sk);
static int PatRarity(int pat);
// редкость зависит от рисунка скина (череп/огонь - легендарные, звёзды/тигр/орнамент/чешуя - эпические, камуфляж/соты/схемы/кристаллы - редкие,
// полосы/волны/точки - обычные); радужный эффект на ступень выше; ножи тоже на ступень выше
static int SkinRarity(int w, int sk) {
    if (sk <= 0 || sk >= NUM_SKINS) return R_COMMON;
    int r = PatRarity(SkinPattern(w, sk));
    if (SKINS[w][sk].fx == FX_RAINBOW) r++;
    if (w >= W_KNIFE) r++;
    return std::min(r, (int)R_LEGEND);
}


// =====================================================================
//  СКИНЫ ПЕРСОНАЖА: ПЕРЧАТКИ И ФОРМЫ (3.4)
//  Слот 0 - перчатки (руки в первом лице и у модели), слот 1 - форма (рукава, куртка, штаны, жилет).
//  Падают из GEAR CASE (золото) и GEAR BOX (серебро). Сохранение: sandstrike_gear.cfg.
// =====================================================================
#define NUM_GSKIN 7
struct GearDef { const char* name; Color a, b, c; uint8_t fx, rar; };
#define GC(r, g, b) Color{ r, g, b, 255 }
static const GearDef GEAR[2][NUM_GSKIN] = {
    { { "Default", GC(44,38,32), GC(30,26,22), GC(24,22,20), FX_NONE, R_COMMON },
      { "Leather Grip", GC(120,78,44), GC(70,44,24), GC(58,36,20), FX_NONE, R_COMMON },
      { "Arctic Mitts", GC(232,238,246), GC(90,170,255), GC(150,170,190), FX_NONE, R_COMMON },
      { "Desert Camo", GC(166,144,98), GC(104,90,58), GC(86,74,46), FX_CAMO, R_RARE },
      { "Racing Red", GC(205,28,32), GC(245,245,245), GC(120,16,18), FX_NONE, R_RARE },
      { "Neon Grip", GC(20,225,200), GC(255,40,200), GC(14,120,110), FX_PULSE, R_EPIC },
      { "Prism Wraps", GC(255,255,255), GC(255,255,255), GC(160,160,170), FX_RAINBOW, R_LEGEND } },
    { { "Default", GC(46,60,92), GC(36,44,66), GC(30,34,42), FX_NONE, R_COMMON },
      { "Woodland", GC(76,98,56), GC(58,74,44), GC(44,56,34), FX_CAMO, R_COMMON },
      { "Urban Grey", GC(112,116,122), GC(72,76,84), GC(42,46,54), FX_NONE, R_COMMON },
      { "Desert Ops", GC(192,162,102), GC(152,128,82), GC(102,86,58), FX_CAMO, R_RARE },
      { "Crimson Guard", GC(168,28,34), GC(40,24,26), GC(24,22,24), FX_NONE, R_RARE },
      { "Neon Runner", GC(22,32,64), GC(14,18,38), GC(20,225,200), FX_PULSE, R_EPIC },
      { "Prism Suit", GC(255,255,255), GC(40,40,52), GC(60,60,76), FX_RAINBOW, R_LEGEND } }
};
static const char* GEAR_NAME[2] = { "GLOVES", "UNIFORM" };
static int gGearSkin[2] = {};
static uint8_t gGearOwn[2] = {};

static Color GearFx(Color a, Color acc, int fx, float ph) {
    float t = (float)GetTime();
    switch (fx) {
        case FX_GRAD:    return MixC(a, acc, 0.5f + 0.5f * sinf(t * 1.5f + ph));
        case FX_PULSE:   return MixC(a, acc, 0.45f * (0.5f + 0.5f * sinf(t * 2.5f + ph)));
        case FX_CAMO:    return MixC(a, acc, 0.30f);
        case FX_RAINBOW: return ColorFromHSV(fmodf(t * 70.0f + ph * 40.0f, 360.0f), 0.8f, 0.95f);
        default:         return a;
    }
}
static Color GearMain(int slot, int sk) { const GearDef& g = GEAR[slot][sk]; return GearFx(g.a, slot == 0 ? g.b : g.c, g.fx, 0.0f); }
static Color GearHandCol()   { return gGearSkin[0] > 0 ? GearMain(0, gGearSkin[0]) : PAL[C_SKIN]; }
static Color GearSleeveCol() { return gGearSkin[1] > 0 ? GearMain(1, gGearSkin[1]) : PAL[C_SLEEVE]; }

static void GearSave() {
    char buf[96];
    snprintf(buf, sizeof(buf), "SSGEAR 1 %d %d %d %d", gGearSkin[0], gGearSkin[1], (int)gGearOwn[0], (int)gGearOwn[1]);
    SaveFileText("sandstrike_gear.cfg", buf);
}
static void GearLoad() {
    char* t = LoadFileText("sandstrike_gear.cfg");
    if (!t) return;
    int v, a, b, o0, o1;
    if (sscanf(t, "SSGEAR %d %d %d %d %d", &v, &a, &b, &o0, &o1) == 5) {
        gGearOwn[0] = (uint8_t)((o0 & 0x7F) | 1); gGearOwn[1] = (uint8_t)((o1 & 0x7F) | 1);
        gGearSkin[0] = (a >= 0 && a < NUM_GSKIN) ? a : 0; gGearSkin[1] = (b >= 0 && b < NUM_GSKIN) ? b : 0;
    }
    UnloadFileText(t);
}

// единый доступ к предметам кейсов: w < NUM_VIS - оружие/нож, иначе слот снаряжения w - NUM_VIS
static bool IsGear(int w) { return w >= NUM_VIS; }
static const char* GItemName(int w) { return IsGear(w) ? GEAR_NAME[w - NUM_VIS] : VisName(w); }
static const char* ItemSkinName(int w, int sk) { return IsGear(w) ? GEAR[w - NUM_VIS][sk].name : SKINS[w][sk].name; }
static int ItemRar(int w, int sk) { return IsGear(w) ? GEAR[w - NUM_VIS][sk].rar : SkinRarity(w, sk); }
static void ItemColors(int w, int sk, Color* o) {
    if (IsGear(w)) { const GearDef& g = GEAR[w - NUM_VIS][sk]; o[0] = g.a; o[1] = g.b; o[2] = g.c; }
    else { const SkinDef& k = SKINS[w][sk]; o[0] = k.body; o[1] = k.metal; o[2] = k.accent; }
}
static int GearOwnedCount() { int n = 0; for (int g = 0; g < 2; g++) for (int s = 1; s < NUM_GSKIN; s++) if ((gGearOwn[g] >> s) & 1) n++; return n; }

struct CaseDef { const char* name; bool gold; int price; bool knives; int wt[NUM_RAR]; Color col; bool gear; };
static const int NUM_CASES = 6;
static const CaseDef CASES[NUM_CASES] = {
    { "WEAPON CASE", true,   50, false, {  0, 55, 33, 12 }, { 255, 170,  40, 255 } },
    { "KNIFE CASE",  true,  150, true,  {  0, 50, 35, 15 }, { 235,  80,  60, 255 } },
    { "WEAPON BOX",  false, 1200, false, { 70, 25,  5,  0 }, { 120, 170, 210, 255 } },
    { "KNIFE BOX",   false, 3500, true,  {  0, 80, 18,  2 }, { 150, 150, 170, 255 } },
    { "GEAR CASE",   true,   40, false, { 30, 40, 22,  8 }, {  90, 200, 120, 255 }, true },
    { "GEAR BOX",    false,  900, false, { 60, 30, 9,  1 }, { 110, 190, 170, 255 }, true },
};

static int gGold = 100, gSilver = 3000;     // стартовый баланс
static long gLastDaily = -1;                // номер дня последнего ежедневного бонуса
static uint8_t gOwn[NUM_VIS] = {};          // бит sk = скин sk куплен (бит 0 - стандартный, всегда)
static bool gInvDirty = false;
static bool Owns(int w, int sk) { return sk <= 0 || (sk < NUM_SKINS && ((gOwn[w] >> sk) & 1)); }
static int OwnedCount() { int n = 0; for (int w = 0; w < NUM_VIS; w++) for (int s = 1; s < NUM_SKINS; s++) if (Owns(w, s)) n++; return n; }
static bool ItemOwns(int w, int sk) { return IsGear(w) ? (sk <= 0 || ((gGearOwn[w - NUM_VIS] >> sk) & 1)) : Owns(w, sk); }
static void ItemGive(int w, int sk) { if (IsGear(w)) gGearOwn[w - NUM_VIS] |= (uint8_t)(1 << sk); else gOwn[w] |= (uint8_t)(1 << sk); }

static void InvSave() {
    char buf[512];
    int n = snprintf(buf, sizeof(buf), "SSINV 1 %d %d %ld %d", gGold, gSilver, gLastDaily, (int)NUM_VIS);
    for (int i = 0; i < NUM_VIS && n > 0 && n < (int)sizeof(buf) - 12; i++) n += snprintf(buf + n, sizeof(buf) - n, " %d", (int)gOwn[i]);
    SaveFileText("sandstrike_inv.cfg", buf);
    gInvDirty = false;
}
static void InvLoad() {   // вызывать после SkinsLoad: скины, надетые в старых версиях, остаются у игрока
    char* t = LoadFileText("sandstrike_inv.cfg");
    if (t) {
        int ver = 0, g = 0, s = 0, cnt = 0, off = 0; long d = -1;
        if (sscanf(t, "SSINV %d %d %d %ld %d%n", &ver, &g, &s, &d, &cnt, &off) == 5 && ver == 1 && cnt > 0 && cnt <= NUM_VIS) {
            uint8_t tmp[NUM_VIS] = {}; const char* p = t + off; bool ok = true;
            for (int i = 0; i < cnt; i++) { int v, o2 = 0; if (sscanf(p, " %d%n", &v, &o2) != 1) { ok = false; break; } p += o2; tmp[i] = (uint8_t)(v & 0x1F); }
            if (ok) { gGold = std::max(0, g); gSilver = std::max(0, s); gLastDaily = d; for (int i = 0; i < NUM_VIS; i++) gOwn[i] = tmp[i]; }
        }
        UnloadFileText(t);
    }
    for (int i = 0; i < NUM_VIS; i++) {
        gOwn[i] |= 1;
        if (gSkin[i] > 0 && gSkin[i] < NUM_SKINS) gOwn[i] |= (uint8_t)(1 << gSkin[i]);   // уже надетое - уже твоё
    }
}
static void AddGold(int v)   { gGold   = std::min(gGold   + v, 99999999); gInvDirty = true; }
static void AddSilver(int v) { gSilver = std::min(gSilver + v, 99999999); gInvDirty = true; }

// ===== УРОВНИ, ОПЫТ И ЕЖЕДНЕВНЫЕ ЗАДАНИЯ =====
struct Prog { long xp = 0; int kills = 0, deaths = 0, heads = 0, rwins = 0, mwins = 0; long day = -1; int qp[3] = { 0, 0, 0 }; int qc[3] = { 0, 0, 0 }; };
static Prog gP;
static int gQTarget[3] = { 10, 3, 2 }, gQGold[3] = { 15, 20, 25 }, gQSilver[3] = { 300, 400, 500 };
static const char* QNAME[3] = { "Get %d kills", "Get %d headshot kills", "Win %d rounds" };
static int XpForLevel(int lvl) { return 100 + 60 * (lvl - 1); }      // опыта нужно с уровня lvl на lvl+1
static int ProgLevel(long* into = nullptr, int* need = nullptr) {
    long x = gP.xp; int l = 1;
    while (x >= XpForLevel(l) && l < 100) { x -= XpForLevel(l); l++; }
    if (into) *into = x; if (need) *need = XpForLevel(l);
    return l;
}
static int LvlRewardGold(int l)   { return (l % 5 == 0) ? 25 : 3; }
static int LvlRewardSilver(int l) { return 150 + 50 * l; }
static const char* RankName(int l) {
    if (l >= 50) return "LEGEND"; if (l >= 35) return "MASTER"; if (l >= 25) return "ELITE";
    if (l >= 15) return "VETERAN"; if (l >= 8) return "SOLDIER"; if (l >= 3) return "RECRUIT"; return "ROOKIE";
}
static void ProgSave() {
    char b[320];
    snprintf(b, sizeof(b), "SSPRG 1 %ld %d %d %d %d %d %ld %d %d %d %d %d %d", gP.xp, gP.kills, gP.deaths, gP.heads, gP.rwins, gP.mwins, gP.day,
             gP.qp[0], gP.qp[1], gP.qp[2], gP.qc[0], gP.qc[1], gP.qc[2]);
    SaveFileText("sandstrike_prog.cfg", b);
}
static void ProgDayCheck() {
    long day = (long)(time(NULL) / 86400);
    if (gP.day == day) return;
    gP.day = day;
    for (int i = 0; i < 3; i++) { gP.qp[i] = 0; gP.qc[i] = 0; }
    ProgSave();
}
static void ProgQuestInit() {   // цели зависят от дня, так что одинаковы весь день
    long d = (long)(time(NULL) / 86400);
    static const int K[3] = { 10, 15, 20 }, H[3] = { 3, 5, 8 }, W[3] = { 2, 3, 4 };
    gQTarget[0] = K[d % 3]; gQTarget[1] = H[(d / 3) % 3]; gQTarget[2] = W[(d / 9) % 3];
    for (int i = 0; i < 3; i++) { gQGold[i] = 10 + gQTarget[i] * (i == 1 ? 4 : (i == 2 ? 8 : 1)); gQSilver[i] = 100 * (i + 2); }
}
static void ProgLoad() {
    char* t = LoadFileText("sandstrike_prog.cfg");
    if (t) {
        Prog q; int ver = 0;
        if (sscanf(t, "SSPRG %d %ld %d %d %d %d %d %ld %d %d %d %d %d %d", &ver, &q.xp, &q.kills, &q.deaths, &q.heads, &q.rwins, &q.mwins, &q.day,
                   &q.qp[0], &q.qp[1], &q.qp[2], &q.qc[0], &q.qc[1], &q.qc[2]) == 14 && ver == 1) gP = q;
        UnloadFileText(t);
    }
    ProgQuestInit(); ProgDayCheck();
}
// выдаёт опыт; возвращает true, если получен новый уровень (награда выдаётся сразу)
static bool ProgAddXp(int v) {
    int before = ProgLevel();
    gP.xp += v;
    int after = ProgLevel();
    for (int l = before; l < after; l++) { AddGold(LvlRewardGold(l + 1)); AddSilver(LvlRewardSilver(l + 1)); }
    return after > before;
}
static bool ProgKill(bool head) {
    ProgDayCheck();
    gP.kills++; gP.qp[0]++;
    if (head) { gP.heads++; gP.qp[1]++; }
    bool up = ProgAddXp(head ? 15 : 10);
    gInvDirty = true; ProgSave();
    return up;
}
static void ProgDeath() { ProgDayCheck(); gP.deaths++; ProgSave(); }
static bool ProgWin(bool match) {
    ProgDayCheck();
    if (match) gP.mwins++; else { gP.rwins++; }
    gP.qp[2]++;
    bool up = ProgAddXp(match ? 150 : 50);
    ProgSave();
    return up;
}

// случайный скин из кейса: сначала выбирается редкость по весам, потом скин этой редкости
static void RollSkin(const CaseDef& c, int& rw, int& rs) {
    int tot = 0; for (int i = 0; i < NUM_RAR; i++) tot += c.wt[i];
    int r = rand() % std::max(1, tot), rar = R_COMMON;
    for (int i = 0; i < NUM_RAR; i++) { if (r < c.wt[i]) { rar = i; break; } r -= c.wt[i]; }
    std::vector<std::pair<int, int>> cand;
    for (int d = 0; d < NUM_RAR && cand.empty(); d++) {
        for (int dir = 0; dir < 2 && cand.empty(); dir++) {
            int rr = dir == 0 ? rar - d : rar + d;
            if (rr < 0 || rr >= NUM_RAR) continue;
            if (c.gear) { for (int g = 0; g < 2; g++) for (int s = 1; s < NUM_GSKIN; s++) if (GEAR[g][s].rar == rr) cand.push_back({ NUM_VIS + g, s }); continue; }
            for (int w = 0; w < NUM_VIS; w++) {
                if ((w >= W_KNIFE) != c.knives) continue;
                for (int s = 1; s < NUM_SKINS; s++) if (SkinRarity(w, s) == rr) cand.push_back({ w, s });
            }
        }
    }
    auto pk = cand[rand() % cand.size()];
    rw = pk.first; rs = pk.second;
}

// цвет детали p (номер idx) оружия w с учётом скина
static Color PartColor(int w, int skin, const Part& p, int idx) {
    if (skin <= 0 || skin >= NUM_SKINS) return PAL[p.c];
    const SkinDef& sk = SKINS[w][skin];
    float t = (float)GetTime();
    bool body = (p.c == C_POLY || p.c == C_WOOD || p.c == C_TAN || p.c == C_GREEN) || p.f == 2 || idx == gMain[w];
    if (body) {
        Color b = sk.body;
        switch (sk.fx) {
            case FX_GRAD: {
                float z = Clamp((p.z - gZmin[w]) / std::max(0.01f, gZmax[w] - gZmin[w]), 0.0f, 1.0f);
                b = MixC(sk.body, sk.accent, z);
            } break;
            case FX_PULSE: b = MixC(sk.body, sk.accent, 0.45f * (0.5f + 0.5f * sinf(t * 2.5f + p.z * 3.0f))); break;
            case FX_CAMO: { int k = idx % 3; b = (k == 0) ? sk.body : (k == 1 ? Mul(sk.body, 0.62f) : sk.accent); } break;
            case FX_RAINBOW: b = ColorFromHSV(fmodf(t * 70.0f + p.z * 260.0f + idx * 20.0f, 360.0f), 0.8f, 0.95f); break;
            default: break;
        }
        return p.c == C_POLY ? Mul(b, 0.85f) : b;
    }
    if (p.c == C_METAL) return sk.metal;
    if (p.c == C_STEEL) return MixC(sk.metal, Color{ 170, 172, 182, 255 }, 0.5f);
    if (p.c == C_GOLD) return sk.accent;
    return PAL[p.c];
}
static Color SkinStripeColor(const SkinDef& sk) {
    float t = (float)GetTime();
    if (sk.fx == FX_RAINBOW) return ColorFromHSV(fmodf(t * 70.0f + 180.0f, 360.0f), 1.0f, 1.0f);
    if (sk.fx == FX_PULSE) return Mul(sk.accent, 0.65f + 0.35f * sinf(t * 4.0f));
    return sk.accent;
}

// ---- формы деталей оружия: цилиндр / конус (k = 1..3) и трапециевидная пластина (k = 4) ----
// Освещение здесь «запечённое»: яркость грани зависит от направления её нормали (как у DrawTexBox).
static float FaceShade(float nx, float ny, float nz) {
    return nx * nx * (nx > 0.0f ? 0.90f : 0.84f) + ny * ny * (ny > 0.0f ? 1.00f : 0.50f) + nz * nz * (nz > 0.0f ? 0.78f : 0.66f);
}
// четырёхугольная грань; порядок вершин подбирается сам, чтобы грань смотрела наружу от центра детали (cen)
static void PartQuad(Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector3 cen, Color tint) {
    Vector3 n = Vector3Add(Vector3CrossProduct(Vector3Subtract(b, a), Vector3Subtract(c, a)),
                           Vector3CrossProduct(Vector3Subtract(c, a), Vector3Subtract(d, a)));
    float len = Vector3Length(n);
    if (len < 1e-12f) return;
    n = Vector3Scale(n, 1.0f / len);
    Vector3 mid = Vector3Scale(Vector3Add(Vector3Add(a, b), Vector3Add(c, d)), 0.25f);
    if (Vector3DotProduct(n, Vector3Subtract(mid, cen)) < 0.0f) { Vector3 t = b; b = d; d = t; n = Vector3Negate(n); }
    float k = FaceShade(n.x, n.y, n.z);
    rlColor4ub((unsigned char)(tint.r * k), (unsigned char)(tint.g * k), (unsigned char)(tint.b * k), tint.a);
    rlNormal3f(n.x, n.y, n.z);
    rlTexCoord2f(0, 0); rlVertex3f(a.x, a.y, a.z);
    rlTexCoord2f(1, 0); rlVertex3f(b.x, b.y, b.z);
    rlTexCoord2f(1, 1); rlVertex3f(c.x, c.y, c.z);
    rlTexCoord2f(0, 1); rlVertex3f(d.x, d.y, d.z);
}
// точка цилиндра: (a, b) - поперечные координаты, ax - вдоль оси (k: 1 = ось Z, 2 = ось Y, 3 = ось X)
static Vector3 CylPt(int k, float a, float b, float ax) {
    if (k == 1) return Vector3{ a, b, ax };
    if (k == 2) return Vector3{ a, ax, b };
    return Vector3{ ax, a, b };
}
// цилиндр (граней 8, у толстых 12) с центром в (cx,cy,cz); p.a > 0 - во сколько раз сужается торец со стороны +оси
// k=1: диаметры w (X) и h (Y), длина l;  k=2: диаметры w (X) и l (Z), длина h;  k=3: диаметры h (Y) и l (Z), длина w
static void DrawPartCyl(const Part& p, float cx, float cy, float cz, Color tint) {
    float d1, d2, L;
    if (p.k == 1) { d1 = p.w; d2 = p.h; L = p.l; }
    else if (p.k == 2) { d1 = p.w; d2 = p.l; L = p.h; }
    else { d1 = p.h; d2 = p.l; L = p.w; }
    const float t = p.a > 0.0f ? p.a : 1.0f;
    const int N = (std::max(d1, d2) > 0.045f) ? 12 : 8;
    Vector3 cen = { cx, cy, cz };
    Vector3 r0[12], r1[12];
    for (int i = 0; i < N; i++) {
        float ang = 2.0f * PI * ((float)i + 0.5f) / (float)N;
        float ca = cosf(ang) * d1 * 0.5f, sa = sinf(ang) * d2 * 0.5f;
        r0[i] = Vector3Add(cen, CylPt(p.k, ca, sa, -L * 0.5f));
        r1[i] = Vector3Add(cen, CylPt(p.k, ca * t, sa * t, L * 0.5f));
    }
    rlCheckRenderBatchLimit(8 * N + 8);
    rlSetTexture(rlGetTextureIdDefault());
    rlBegin(RL_QUADS);
    for (int i = 0; i < N; i++) {
        int j = (i + 1) % N;
        PartQuad(r0[i], r0[j], r1[j], r1[i], cen, tint);
    }
    Vector3 c0 = Vector3Add(cen, CylPt(p.k, 0, 0, -L * 0.5f)), c1 = Vector3Add(cen, CylPt(p.k, 0, 0, L * 0.5f));
    for (int i = 0; i < N; i += 2) {
        PartQuad(c0, r0[i], r0[(i + 1) % N], r0[(i + 2) % N], cen, tint);
        PartQuad(c1, r1[i], r1[(i + 1) % N], r1[(i + 2) % N], cen, tint);
    }
    rlEnd();
    rlSetTexture(0);
}
// трапециевидная пластина: профиль в плоскости Y-Z (клинки, приклады, скосы), толщина w по X.
// Сзади (z - l/2) высота h с центром y - b/2, спереди (z + l/2) высота a (если a = 0, то h) с центром y + b/2
static void DrawPartSlab(const Part& p, float cx, float cy, float cz, Color tint) {
    float a = p.a > 0.0f ? p.a : p.h;
    float yb = cy - p.b * 0.5f, yf = cy + p.b * 0.5f;
    float x0 = cx - p.w * 0.5f, x1 = cx + p.w * 0.5f, z0 = cz - p.l * 0.5f, z1 = cz + p.l * 0.5f;
    Vector3 v[8] = {
        { x0, yb - p.h * 0.5f, z0 }, { x1, yb - p.h * 0.5f, z0 }, { x1, yb + p.h * 0.5f, z0 }, { x0, yb + p.h * 0.5f, z0 },
        { x0, yf - a * 0.5f, z1 },   { x1, yf - a * 0.5f, z1 },   { x1, yf + a * 0.5f, z1 },   { x0, yf + a * 0.5f, z1 }
    };
    static const int F[6][4] = { { 4, 5, 6, 7 }, { 1, 0, 3, 2 }, { 3, 7, 6, 2 }, { 0, 1, 5, 4 }, { 1, 2, 6, 5 }, { 0, 4, 7, 3 } };
    Vector3 cen = { cx, (yb + yf) * 0.5f, cz };
    rlCheckRenderBatchLimit(32);
    rlSetTexture(rlGetTextureIdDefault());
    rlBegin(RL_QUADS);
    for (int i = 0; i < 6; i++) PartQuad(v[F[i][0]], v[F[i][1]], v[F[i][2]], v[F[i][3]], cen, tint);
    rlEnd();
    rlSetTexture(0);
}
static void DrawPartShape(const Part& p, float cx, float cy, float cz, Color col) {
    if (p.k == 0)
        DrawTexBox(cx - p.w * 0.5f, cy - p.h * 0.5f, cz - p.l * 0.5f, cx + p.w * 0.5f, cy + p.h * 0.5f, cz + p.l * 0.5f, NOTEX, 1.0f, col, true);
    else if (p.k == 4) DrawPartSlab(p, cx, cy, cz, col);
    else DrawPartCyl(p, cx, cy, cz, col);
}
// рисует одну деталь; наклонённая вращается вокруг своего центра (сначала Z, затем X)
static void DrawPartAt(const Part& p, float y, Color col) {
    if (p.rx != 0.0f || p.rz != 0.0f) {
        rlPushMatrix();
        rlTranslatef(p.x, y, p.z);
        if (p.rx != 0.0f) rlRotatef(p.rx, 1, 0, 0);
        if (p.rz != 0.0f) rlRotatef(p.rz, 0, 0, 1);
        DrawPartShape(p, 0.0f, 0.0f, 0.0f, col);
        rlPopMatrix();
    } else {
        DrawPartShape(p, p.x, y, p.z, col);
    }
}

// =====================================================================
//  РИСУНКИ НА СКИНАХ: процедурные текстуры-наклейки (белое с альфой), красятся в акцентный цвет скина
//  и накладываются на боковые грани корпуса / клинка (плиткой, чтобы не растягиваться).
// =====================================================================
enum { PAT_FLAMES, PAT_CAMO, PAT_TIGER, PAT_CIRCUIT, PAT_WAVES, PAT_CRYSTAL, PAT_HEX, PAT_STARS, PAT_SCALES, PAT_SKULL,
       PAT_CHEVRON, PAT_RACING, PAT_ORNAMENT, PAT_ZIGZAG, PAT_SPOTS, PAT_DOTS, NUM_PAT };
static Texture2D gPatTex[NUM_PAT];
static inline float PFr(float x) { return x - floorf(x); }
static inline float PSS(float a, float b, float x) { float t = (x - a) / (b - a); t = t < 0.0f ? 0.0f : (t > 1.0f ? 1.0f : t); return t * t * (3.0f - 2.0f * t); }
static inline unsigned PHash(int x, int y, int s) {
    unsigned h = (unsigned)x * 374761393u + (unsigned)y * 668265263u + (unsigned)s * 2246822519u;
    h = (h ^ (h >> 13)) * 1274126177u; return h ^ (h >> 16);
}
static float PatAlpha(int pat, float u, float v) {
    const float TP = 6.2831853f;
    switch (pat) {
    case PAT_FLAMES: {
        float x = u * 3.0f; int i = (int)floorf(x) % 3; float fx = x - floorf(x) - 0.5f;
        float hgt = 0.55f + 0.38f * ((PHash(i, 0, 1) & 255) / 255.0f);
        float t = (1.0f - v) / hgt; if (t < 0.0f || t >= 1.0f) return 0.0f;
        float off = 0.10f * sinf(t * 6.0f + i * 2.0f), d = fabsf(fx - off);
        float outer = 0.48f * powf(1.0f - t, 0.8f);
        if (d >= outer) return 0.0f;
        float edge = 1.0f - PSS(outer - 0.04f, outer, d);
        float inner = 0.20f * (1.0f - t / 0.75f);
        return (t < 0.75f && d < inner) ? 0.45f : edge;
    }
    case PAT_CAMO: {
        float f = sinf(TP * 2.0f * u + 2.2f * sinf(TP * v)) + sinf(TP * 3.0f * v + 2.2f * sinf(TP * 2.0f * u + 1.0f));
        return PSS(0.15f, 0.30f, f);
    }
    case PAT_TIGER: {
        float s = sinf(TP * (3.0f * u + 0.5f * sinf(TP * 2.0f * v) + 0.15f * sinf(TP * 5.0f * v)));
        s *= 0.7f + 0.3f * sinf(TP * (3.0f * v + 3.0f * u));
        return PSS(0.40f, 0.55f, s);
    }
    case PAT_CIRCUIT: {
        int cx = (int)(u * 8.0f) & 7, cy = (int)(v * 8.0f) & 7;
        float fx = u * 8.0f - floorf(u * 8.0f) - 0.5f, fy = v * 8.0f - floorf(v * 8.0f) - 0.5f;
        unsigned h = PHash(cx, cy, 3); float a = 0.0f, r2 = fx * fx + fy * fy;
        if ((h & 1) && fabsf(fy) < 0.08f) a = 1.0f;
        if ((h & 2) && fabsf(fx) < 0.08f) a = 1.0f;
        if ((h & 16) && fabsf(fx - fy) < 0.07f) a = 1.0f;
        if (!(h & 19) || (h & 4)) { if (r2 < 0.045f) a = 1.0f; }
        if ((h & 8) && r2 > 0.030f && r2 < 0.070f) a = 1.0f;
        if ((h & 8) && r2 <= 0.030f) a = 0.0f;
        return a;
    }
    case PAT_WAVES: {
        float f = PFr(v * 5.0f + 0.25f * sinf(TP * 2.0f * u));
        return PSS(0.0f, 0.08f, f) * (1.0f - PSS(0.30f, 0.38f, f));
    }
    case PAT_CRYSTAL: {
        float x = PFr(u * 4.0f) - 0.5f, y = PFr(v * 4.0f) - 0.5f, d = fabsf(x) + fabsf(y);
        int par = ((int)(u * 4.0f) + (int)(v * 4.0f)) & 1;
        float a = (d > 0.40f && d < 0.5f) ? 1.0f : 0.0f;
        if (!par && d < 0.30f) a = 0.55f;
        if (par && d < 0.12f) a = 1.0f;
        return a;
    }
    case PAT_HEX: {
        int row = (int)(v * 4.0f);
        float x = PFr(u * 4.0f + (row & 1) * 0.5f) - 0.5f, y = PFr(v * 4.0f) - 0.5f;
        float hd = std::max(fabsf(x) * 0.866f + fabsf(y) * 0.5f, fabsf(y));
        float a = PSS(0.38f, 0.42f, hd) * (1.0f - PSS(0.48f, 0.50f, hd));
        if (hd < 0.12f) a = std::max(a, 0.7f);
        return a;
    }
    case PAT_STARS: {
        float a = 0.0f;
        int cx = (int)(u * 3.0f) % 3, cy = (int)(v * 3.0f) % 3; unsigned h = PHash(cx, cy, 7);
        float x = PFr(u * 3.0f) - 0.5f - (((h & 15) / 15.0f) - 0.5f) * 0.25f, y = PFr(v * 3.0f) - 0.5f - ((((h >> 4) & 15) / 15.0f) - 0.5f) * 0.25f;
        float sz = 0.55f + 0.2f * (((h >> 8) & 7) / 7.0f);
        if (sqrtf(fabsf(x)) + sqrtf(fabsf(y)) < sz) a = 1.0f;
        int dx = (int)(u * 8.0f) & 7, dy = (int)(v * 8.0f) & 7; unsigned h2 = PHash(dx, dy, 9);
        if ((h2 & 7) == 0) { float ex = PFr(u * 8.0f) - 0.5f, ey = PFr(v * 8.0f) - 0.5f; if (ex * ex + ey * ey < 0.03f) a = std::max(a, 0.8f); }
        return a;
    }
    case PAT_SCALES: {
        int row = (int)(v * 5.0f);
        float x = PFr(u * 5.0f + (row & 1) * 0.5f) - 0.5f, y = PFr(v * 5.0f);
        float d = sqrtf(x * x + y * y);
        if (d > 0.44f && d < 0.52f) return 1.0f;
        if (d > 0.26f && d < 0.31f) return 0.8f;
        if (d < 0.5f) return 0.30f;
        return 0.0f;
    }
    case PAT_SKULL: {
        float x = u - 0.5f, y = v - 0.5f;
        float ex = x / 0.30f, ey = (y + 0.08f) / 0.27f;
        bool skull = ex * ex + ey * ey < 1.0f;
        if (fabsf(x) < 0.17f && y > 0.10f && y < 0.30f) skull = true;
        bool bone = (fabsf(x - y) < 0.045f || fabsf(x + y) < 0.045f) && fabsf(x) < 0.46f && fabsf(y) < 0.46f;
        bool hole = false;
        float lx = fabsf(x) - 0.115f, ly = y - 0.0f;
        if (lx * lx + ly * ly < 0.0055f) hole = true;
        if (y > 0.06f && y < 0.13f && fabsf(x) < 0.035f * (y - 0.05f) / 0.04f) hole = true;
        if (y > 0.20f && y < 0.30f && fabsf(x) < 0.17f && PFr((x + 0.17f) / 0.068f) < 0.12f) hole = true;
        if (hole) return 0.0f;
        return (skull || bone) ? 1.0f : 0.0f;
    }
    case PAT_CHEVRON: {
        float f = PFr(v * 3.0f + fabsf(u * 2.0f - 1.0f) * 0.5f);
        return PSS(0.0f, 0.05f, f) * (1.0f - PSS(0.40f, 0.45f, f));
    }
    case PAT_RACING:
        return std::max(PSS(0.26f, 0.29f, v) * (1.0f - PSS(0.41f, 0.44f, v)), PSS(0.49f, 0.52f, v) * (1.0f - PSS(0.56f, 0.59f, v)));
    case PAT_ORNAMENT: {
        float x = u - 0.5f, y = v - 0.5f, d = fabsf(x) + fabsf(y), a = 0.0f;
        if (d > 0.36f && d < 0.43f) a = 1.0f;
        if (d > 0.20f && d < 0.25f) a = 1.0f;
        if (x * x + y * y < 0.0064f) a = 1.0f;
        float cx = std::min(u, 1.0f - u), cy = std::min(v, 1.0f - v);
        if (cx * cx + cy * cy < 0.010f) a = 1.0f;
        return a;
    }
    case PAT_ZIGZAG: {
        float tri = fabsf(PFr(u * 3.0f) * 2.0f - 1.0f);
        return 1.0f - PSS(0.05f, 0.09f, fabsf(v - (0.2f + 0.6f * tri)));
    }
    case PAT_SPOTS: {
        int cx = (int)(u * 3.0f) % 3, cy = (int)(v * 3.0f) % 3; unsigned h = PHash(cx, cy, 11);
        float x = PFr(u * 3.0f) - 0.5f - (((h & 15) / 15.0f) - 0.5f) * 0.25f, y = PFr(v * 3.0f) - 0.5f - ((((h >> 4) & 15) / 15.0f) - 0.5f) * 0.25f;
        float d = sqrtf(x * x + y * y);
        if (d < 0.07f) return 1.0f;
        if (d > 0.15f && d < 0.27f && ((h >> 8) & 3) != 0) return 1.0f;
        return 0.0f;
    }
    case PAT_DOTS: {
        int row = (int)(v * 6.0f);
        float x = PFr(u * 6.0f + (row & 1) * 0.5f) - 0.5f, y = PFr(v * 6.0f) - 0.5f;
        float r = 0.20f + 0.08f * (row % 3), d = sqrtf(x * x + y * y);
        return 1.0f - PSS(r - 0.04f, r, d);
    }
    }
    return 0.0f;
}
static int PatRarity(int pat) {
    switch (pat) {
        case PAT_FLAMES: case PAT_SKULL: return R_LEGEND;
        case PAT_STARS: case PAT_TIGER: case PAT_ORNAMENT: case PAT_SCALES: return R_EPIC;
        case PAT_CAMO: case PAT_HEX: case PAT_SPOTS: case PAT_CRYSTAL: case PAT_CIRCUIT: return R_RARE;
        default: return R_COMMON;
    }
}
static void InitSkinPatterns() {
    const int N = 128;
    for (int pt = 0; pt < NUM_PAT; pt++) {
        vector<Color> px((size_t)N * N);
        for (int y = 0; y < N; y++)
            for (int x = 0; x < N; x++) {
                float a = PatAlpha(pt, (x + 0.5f) / N, (y + 0.5f) / N);
                px[(size_t)y * N + x] = Color{ 255, 255, 255, (unsigned char)(Clamp(a, 0.0f, 1.0f) * 255.0f) };
            }
        gPatTex[pt] = MakeTex(N, px);
    }
}
// какой рисунок у скина sk оружия w: по ключевым словам в названии, иначе по эффекту
static int SkinPattern(int w, int sk) {
    if (sk <= 0 || sk >= NUM_SKINS) return -1;
    static int8_t cache[NUM_VIS][NUM_SKINS]; static bool inited = false;
    if (!inited) { for (int i = 0; i < NUM_VIS; i++) for (int j = 0; j < NUM_SKINS; j++) cache[i][j] = -2; inited = true; }
    if (cache[w][sk] != -2) return cache[w][sk];
    static const struct { const char* k; int p; } KW[] = {
        { "Camo", PAT_CAMO }, { "Masked", PAT_CAMO }, { "Dweller", PAT_CAMO }, { "Leopard", PAT_SPOTS }, { "Stained", PAT_SPOTS },
        { "Tiger", PAT_TIGER }, { "Hex", PAT_HEX }, { "Wyrm", PAT_SCALES }, { "Dragonfire", PAT_FLAMES }, { "Dragon", PAT_SCALES },
        { "Damascus", PAT_WAVES }, { "Water", PAT_WAVES }, { "Abyss", PAT_WAVES }, { "Sand", PAT_WAVES }, { "Marble", PAT_WAVES },
        { "Doppler", PAT_WAVES }, { "Sea Glass", PAT_WAVES }, { "Fade", PAT_CHEVRON }, { "Redline", PAT_RACING }, { "Silent", PAT_SKULL },
        { "Toxic", PAT_SKULL }, { "Slaughter", PAT_SKULL }, { "Crimson", PAT_HEX }, { "Neon", PAT_CIRCUIT }, { "Pulse", PAT_CIRCUIT },
        { "Autotronic", PAT_CIRCUIT }, { "Orbit", PAT_STARS }, { "Midnight", PAT_STARS }, { "Night", PAT_STARS }, { "Void", PAT_STARS },
        { "Aurora", PAT_STARS }, { "Ghost", PAT_STARS }, { "Frost", PAT_CRYSTAL }, { "Arctic", PAT_CRYSTAL }, { "Ice", PAT_CRYSTAL },
        { "Emerald", PAT_CRYSTAL }, { "Prism", PAT_CRYSTAL }, { "Ivory", PAT_ORNAMENT }, { "Gold", PAT_ORNAMENT }, { "Antique", PAT_ORNAMENT },
        { "Royal", PAT_ORNAMENT }, { "Plated", PAT_ORNAMENT }, { "Case", PAT_ORNAMENT }, { "Lore", PAT_ORNAMENT }, { "Blaze", PAT_FLAMES },
        { "Inferno", PAT_FLAMES }, { "Lava", PAT_FLAMES }, { "Magma", PAT_FLAMES }, { "Sunset", PAT_CHEVRON }, { "Blue Steel", PAT_CHEVRON },
        { "Charcoal", PAT_CHEVRON }, { "Graffiti", PAT_ZIGZAG }, { "Vaporwave", PAT_ZIGZAG }, { "Hyper", PAT_ZIGZAG }, { "Candy", PAT_DOTS },
        { "Gum", PAT_DOTS }, { "Disco", PAT_DOTS }, { "Lime", PAT_DOTS }, { "Cobalt", PAT_HEX }
    };
    const char* nm = SKINS[w][sk].name; int res = -1;
    for (const auto& e : KW) if (strstr(nm, e.k)) { res = e.p; break; }
    if (res < 0) {
        static const int G[3] = { PAT_FLAMES, PAT_ZIGZAG, PAT_CHEVRON }, P[3] = { PAT_CIRCUIT, PAT_DOTS, PAT_HEX };
        static const int R[2] = { PAT_STARS, PAT_DOTS }, Z[4] = { PAT_CHEVRON, PAT_RACING, PAT_HEX, PAT_CRYSTAL };
        int k = w + sk;
        switch (SKINS[w][sk].fx) {
            case FX_GRAD: res = G[k % 3]; break;
            case FX_PULSE: res = P[k % 3]; break;
            case FX_RAINBOW: res = R[k % 2]; break;
            case FX_CAMO: res = PAT_CAMO; break;
            default: res = Z[k % 4]; break;
        }
    }
    cache[w][sk] = (int8_t)res;
    return res;
}
// цвет рисунка: акцент скина, но если он сливается с корпусом - контрастный
static Color PatColor(int w, int skin) {
    const SkinDef& sk = SKINS[w][skin];
    if (sk.fx == FX_RAINBOW) return Color{ 255, 255, 255, 255 };
    Color c = SkinStripeColor(sk), b = sk.body;
    int d = abs((int)c.r - (int)b.r) + abs((int)c.g - (int)b.g) + abs((int)c.b - (int)b.b);
    if (d < 150) {
        int lum = ((int)b.r * 3 + (int)b.g * 6 + (int)b.b) / 10;
        c = lum > 120 ? Mul(b, 0.30f) : MixC(b, Color{ 255, 255, 255, 255 }, 0.70f);
    }
    return c;
}
// наклейка на обе боковые грани (±X) детали: коробка или пластина; наклонённые детали вращаются как в DrawPartAt
static void DrawPartDecal(const Part& p, float y, int pat, Color tint) {
    if (p.k != 0 && p.k != 4) return;
    if (p.l < 0.07f || p.h < 0.022f || pat < 0 || pat >= NUM_PAT) return;
    float cx = p.x, cy = y, cz = p.z;
    bool rot = p.rx != 0.0f || p.rz != 0.0f;
    if (rot) {
        rlPushMatrix(); rlTranslatef(p.x, y, p.z);
        if (p.rx != 0.0f) rlRotatef(p.rx, 1, 0, 0);
        if (p.rz != 0.0f) rlRotatef(p.rz, 0, 0, 1);
        cx = cy = cz = 0.0f;
    }
    float ya0, ya1, yb0, yb1;     // низ/верх в задней (z0) и передней (z1) кромке
    if (p.k == 4) {
        float a = p.a > 0.0f ? p.a : p.h, yb = cy - p.b * 0.5f, yf = cy + p.b * 0.5f;
        ya0 = yb - p.h * 0.5f; ya1 = yb + p.h * 0.5f; yb0 = yf - a * 0.5f; yb1 = yf + a * 0.5f;
    } else { ya0 = yb0 = cy - p.h * 0.5f; ya1 = yb1 = cy + p.h * 0.5f; }
    float z0 = cz - p.l * 0.5f, z1 = cz + p.l * 0.5f, e = 0.0025f;
    float x1 = cx + p.w * 0.5f + e, x0 = cx - p.w * 0.5f - e;
    float hh = std::max(0.02f, ((ya1 - ya0) + (yb1 - yb0)) * 0.5f);
    float tu = floorf(p.l / hh + 0.5f); tu = tu < 1.0f ? 1.0f : (tu > 6.0f ? 6.0f : tu);
    rlCheckRenderBatchLimit(8);
    rlSetTexture(gPatTex[pat].id);
    rlBegin(RL_QUADS);
    rlColor4ub((unsigned char)(tint.r * 0.90f), (unsigned char)(tint.g * 0.90f), (unsigned char)(tint.b * 0.90f), tint.a);
    rlNormal3f(1, 0, 0);
    rlTexCoord2f(tu, 1); rlVertex3f(x1, ya0, z0);
    rlTexCoord2f(tu, 0); rlVertex3f(x1, ya1, z0);
    rlTexCoord2f(0, 0);  rlVertex3f(x1, yb1, z1);
    rlTexCoord2f(0, 1);  rlVertex3f(x1, yb0, z1);
    rlColor4ub((unsigned char)(tint.r * 0.84f), (unsigned char)(tint.g * 0.84f), (unsigned char)(tint.b * 0.84f), tint.a);
    rlNormal3f(-1, 0, 0);
    rlTexCoord2f(0, 1);  rlVertex3f(x0, ya0, z0);
    rlTexCoord2f(tu, 1); rlVertex3f(x0, yb0, z1);
    rlTexCoord2f(tu, 0); rlVertex3f(x0, yb1, z1);
    rlTexCoord2f(0, 0);  rlVertex3f(x0, ya1, z0);
    rlEnd();
    rlSetTexture(0);
    if (rot) rlPopMatrix();
}

// рисует части модели оружия в локальных координатах (skin: 0 = стандартный вид)
static void DrawParts(int w, float magDy, bool magVis, int skin = 0) {
    const ModelDef& m = MODELS[w];
    for (int i = 0; i < m.n; i++) {
        const Part& p = m.p[i];
        float y = p.y;
        if (p.f == 1) {
            if (!magVis) continue;
            y += magDy;
        }
        DrawPartAt(p, y, PartColor(w, skin, p, i));
        if (skin > 0 && skin < NUM_SKINS) {
            bool isBody = (p.c == C_POLY || p.c == C_WOOD || p.c == C_TAN || p.c == C_GREEN) || p.f == 2 || i == gMain[w];
            if (isBody) DrawPartDecal(p, y, SkinPattern(w, skin), PatColor(w, skin));
        }
        if (skin > 0 && skin < NUM_SKINS && i == gMain[w]) {
            // декоративная полоса: сверху и по бокам главной детали
            Color ac = SkinStripeColor(SKINS[w][skin]);
            float top = p.y + p.h * 0.5f;
            DrawTexBox(p.x - p.w * 0.16f, top, p.z - p.l * 0.42f, p.x + p.w * 0.16f, top + 0.005f, p.z + p.l * 0.42f, NOTEX, 1.0f, ac, true);
            for (int sx = -1; sx <= 1; sx += 2) {
                float xo = p.x + sx * p.w * 0.5f, xe = xo + sx * 0.005f;
                DrawTexBox(std::min(xo, xe), p.y + p.h * 0.05f, p.z - p.l * 0.40f, std::max(xo, xe), p.y + p.h * 0.28f, p.z + p.l * 0.40f, NOTEX, 1.0f, ac, true);
            }
        }
    }
}

// =====================================================================
//  КАРТА
// =====================================================================
enum { K_WALL, K_CRATE, K_STONE, K_BARREL };
struct Wall {
    float x0, z0, x1, z1, h;
    float y0 = 0.0f;
    int kind;
    float shade;
    BoundingBox bb;
};
static vector<Wall> gWalls;

enum { D_BRICK, D_WOOD, D_AWNING, D_BUILD, D_DOME };
struct Deco { int kind; float x0, y0, z0, x1, y1, z1; Color a, b; };
static vector<Deco> gDecos;


// ---------------------------------------------------------------------
//  ЗОНЫ КАРТ: у каждой карты свои «примочки»
// ---------------------------------------------------------------------
enum { Z_ICE, Z_SLOW, Z_HURT, Z_GAS, Z_PAD, Z_CONV, Z_HEAL };
// s: ICE - «сцепление» (меньше = скользче); SLOW - множитель скорости; HURT/GAS - урон в секунду; PAD - вертикальная скорость прыжка;
//    CONV - скорость ленты; HEAL - лечение в секунду. dx,dz - направление (PAD, CONV). ph - сдвиг фазы газа (GAS)
struct Zone { int kind; float x0, z0, x1, z1, s, dx, dz, ph; Color c; };
static vector<Zone> gZones;
static float gMapClock = 0.0f;
static const char* gDeathCause = nullptr;
static void AddZone(int kind, float x0, float z0, float x1, float z1, float s, Color c, float dx = 0.0f, float dz = 0.0f, float ph = 0.0f) {
    gZones.push_back(Zone{ kind, x0, z0, x1, z1, s, dx, dz, ph, c });
}
static void ZM(int kind, float x0, float z0, float x1, float z1, float s, Color c, float dx = 0.0f, float dz = 0.0f, float ph = 0.0f) {   // зона + зеркальная копия по X
    AddZone(kind, x0, z0, x1, z1, s, c, dx, dz, ph);
    AddZone(kind, -x1, z0, -x0, z1, s, c, -dx, dz, ph);
}
static inline bool InZone(const Zone& z, float x, float zz) { return x >= z.x0 && x <= z.x1 && zz >= z.z0 && zz <= z.z1; }
static inline float GasPhase(const Zone& z) { return fmodf(gMapClock + z.ph, 12.0f); }   // цикл 12 с: 0..6 тихо, 6..8 предупреждение, 8..12 выброс
static inline bool GasOn(const Zone& z) { return GasPhase(z) >= 8.0f; }
static const char* MapTip(int m) {
    switch (m) {
        case 0: return "CLASSIC: green MEDIC pads heal 8 HP/s - fall back and patch up.";
        case 1: return "COMPOUND: the tunnel belt drags you west; a medic pad sits in the yard.";
        case 2: return "FROST: the central lake is ICE - you slide. Deep snow on the flanks slows you.";
        case 3: return "JUNGLE: the river and undergrowth slow you down. Cross at the three bridges.";
        case 4: return "DUSK: orange JUMP PADS launch you onto the mesas above both sites. Dunes slow you.";
        case 5: return "NEON: moving walkways. The cyan belt runs toward T, the pink belt toward CT.";
        case 6: return "LAVA: a lava channel splits the map (30 dmg/s). Cross by the bridges; geysers erupt on a timer.";
        case 7: return "HARBOR: the canal is deep water (slow). Jump pads put you on container tops.";
        case 8: return "TOXIC: gas vents burst on a timer - watch the green glow. Acid pools burn.";
    }
    return "";
}

static void AddBlock(float x0, float z0, float x1, float z1, float h, int kind) {
    Wall w;
    w.x0 = x0; w.z0 = z0; w.x1 = x1; w.z1 = z1; w.h = h; w.kind = kind;
    w.shade = 0.92f + 0.12f * H01((int)gWalls.size(), 5, 99);
    w.bb = BoundingBox{ Vector3{ x0, 0.0f, z0 }, Vector3{ x1, h, z1 } };
    gWalls.push_back(w);
}
static void AddBlockY(float x0, float y0, float z0, float x1, float z1, float h, int kind) {
    AddBlock(x0, z0, x1, z1, h, kind);
    gWalls.back().y0 = y0;
    gWalls.back().bb.min.y = y0;
}
static void AddDeco(int kind, float x0, float y0, float z0, float x1, float y1, float z1, Color a, Color b) {
    gDecos.push_back(Deco{ kind, x0, y0, z0, x1, y1, z1, a, b });
}

