// ---------------------------------------------------------------------
//  КАРТА 2 (Compound) - по скетчу; координаты считаются из пикселей картинки
//  картинка повёрнута: T слева -> +Z (юг), CT справа -> -Z (север)
// ---------------------------------------------------------------------
struct IGap { int side; float a, b; };   // side: 0 верх, 1 низ, 2 лево, 3 право; a..b - вдоль стороны (пиксели)
static void IB(float x0, float y0, float x1, float y1, float h, int kind) {
    AddBlock((y0 - 370.0f) * 0.12f, (510.0f - x1) * 0.12f, (y1 - 370.0f) * 0.12f, (510.0f - x0) * 0.12f, h, kind);
}
static void IStrip(bool alongX, float x0, float y0, float x1, float y1, float h, int kind, int side, const vector<IGap>& g) {
    float a0 = alongX ? x0 : y0, a1 = alongX ? x1 : y1;
    vector<std::pair<float, float>> cuts;
    for (const IGap& q : g) if (q.side == side) cuts.push_back({ q.a, q.b });
    std::sort(cuts.begin(), cuts.end());
    auto emit = [&](float s, float e) { if (e - s < 1.0f) return; if (alongX) IB(s, y0, e, y1, h, kind); else IB(x0, s, x1, e, h, kind); };
    float cur = a0;
    for (auto& c : cuts) { if (c.first > cur) emit(cur, c.first); cur = std::max(cur, c.second); }
    if (cur < a1) emit(cur, a1);
}
static void IRoom(float x0, float y0, float x1, float y1, float t, float h, const vector<IGap>& g) {
    IStrip(true, x0, y0, x1, y0 + t, h, K_WALL, 0, g);
    IStrip(true, x0, y1 - t, x1, y1, h, K_WALL, 1, g);
    IStrip(false, x0, y0 + t, x0 + t, y1 - t, h, K_WALL, 2, g);
    IStrip(false, x1 - t, y0 + t, x1, y1 - t, h, K_WALL, 3, g);
}

