static void ZonesCompound() {
    AddZone(Z_CONV, 2, -37, 20, -32.5f, 4.5f, Col(255, 190, 60, 170), -1, 0);
    AddZone(Z_HEAL, -7, -1, -3, 3, 8.0f, Col(60, 220, 120, 170));
}
static void ApplyTheme() {
    int id = (gMap >= 2 && gMap <= 8) ? gMap : 0;
    if (id == gThemeId && texPlaster.id != 0) return;
    gThemeId = id;
    if (texPlaster.id) { UnloadTexture(texPlaster); UnloadTexture(texBrick); UnloadTexture(texFloor); UnloadTexture(texCrate); }
    texPlaster = GenPlaster(); texBrick = GenBrick(); texFloor = GenFloor(); texCrate = GenCrate();
}
static void BuildMap() {
    gWalls.clear(); gDecos.clear(); gZones.clear();
    ApplyTheme();
    if (gMap == 1) BuildMap1(); else if (gMap == 2) BuildMap2(); else if (gMap == 3) BuildMap3(); else if (gMap == 4) BuildMap4(); else if (gMap == 5) BuildMap5(); else if (gMap == 6) BuildMap6(); else if (gMap == 7) BuildMap7(); else if (gMap == 8) BuildMap8(); else BuildMap0();
    if (gMap == 0) ZonesClassic(); else if (gMap == 1) ZonesCompound();
}

// ---------------------------------------------------------------------
//  НАВИГАЦИОННЫЙ ГРАФ ДЛЯ БОТОВ
// ---------------------------------------------------------------------
static vector<Vector2> gNodes;
static vector<vector<int>> gAdj;
static int NODE_A = 28;
static int NODE_B = 20;
static int A_GUARD[5] = { 28, 29, 30, 27, 26 };
static int B_GUARD[5] = { 20, 21, 22, 19, 23 };

static bool SegClear(Vector2 a, Vector2 b, float m) {
    float d = Vector2Distance(a, b);
    int n = (int)(d / 0.5f) + 1;
    for (int i = 0; i <= n; i++) {
        float t = (float)i / (float)n;
        float px = a.x + (b.x - a.x) * t, pz = a.y + (b.y - a.y) * t;
        for (const Wall& w : gWalls)
            if (px > w.x0 - m && px < w.x1 + m && pz > w.z0 - m && pz < w.z1 + m) return false;
    }
    return true;
}
static int gLanes[3] = { 12, 7, 16 };
static void BuildGraph() {
    gLanes[0] = 12; gLanes[1] = 7; gLanes[2] = 16;
    if (gMap >= 2) {
        gNodes.clear();
        for (float x = -46.0f; x <= 46.0f; x += 6.0f)
            for (float z = -58.0f; z <= 58.0f; z += 6.0f) {
                bool ok = true;
                for (const Wall& w : gWalls) if (x > w.x0 - 1.0f && x < w.x1 + 1.0f && z > w.z0 - 1.0f && z < w.z1 + 1.0f) { ok = false; break; }
                if (ok) for (const Zone& zn : gZones)
                    if ((zn.kind == Z_HURT || zn.kind == Z_GAS || zn.kind == Z_PAD) && x > zn.x0 - 1.0f && x < zn.x1 + 1.0f && z > zn.z0 - 1.0f && z < zn.z1 + 1.0f) { ok = false; break; }
                if (ok) gNodes.push_back(Vector2{ x, z });
            }
        auto nearK = [&](Vector2 p, int* out) {
            vector<std::pair<float, int>> d;
            for (int i = 0; i < (int)gNodes.size(); i++) d.push_back({ Vector2Distance(p, gNodes[i]), i });
            std::sort(d.begin(), d.end());
            for (int k = 0; k < 5; k++) out[k] = d[std::min(k, (int)d.size() - 1)].second;
        };
        nearK(SITE_A, A_GUARD); nearK(SITE_B, B_GUARD);
        NODE_A = A_GUARD[0]; NODE_B = B_GUARD[0];
        int l[3]; nearK(Vector2{ -26.0f, 0.0f }, l); gLanes[0] = l[0];
        nearK(Vector2{ 0.0f, 20.0f }, l); gLanes[1] = l[0];
        nearK(Vector2{ 26.0f, 0.0f }, l); gLanes[2] = l[0];
    } else if (gMap == 1) {
        gNodes = { {12.0f,49.2f},{7.2f,42.0f},{3.6f,38.4f},{13.2f,38.4f},{9.6f,30.0f},{8.4f,21.6f},{15.6f,20.4f},{15.6f,10.8f},{24.0f,9.6f},{32.4f,8.4f},{38.4f,-9.6f},{27.6f,-6.0f},{27.6f,-15.6f},{25.8f,-23.3f},{28.8f,-30.0f},{21.0f,-34.8f},{13.2f,-34.8f},{1.2f,-34.8f},{-7.2f,-22.8f},{3.6f,-16.8f},{-2.4f,-9.6f},{-4.8f,1.2f},{15.6f,-6.0f},{-25.2f,1.2f},{-24.0f,-10.8f},{-16.2f,-18.6f},{-24.0f,-33.6f},{-33.0f,-34.6f},{-24.0f,-46.8f},{-29.4f,-50.4f},{-14.4f,-39.6f},{-11.9f,-48.8f},{-3.6f,-50.4f},{3.0f,-52.8f},{-24.0f,31.2f},{-9.6f,30.0f},{-13.2f,9.6f},{-3.6f,8.4f},{-22.8f,21.6f},{-28.8f,32.4f},{-26.4f,-6.0f},{-9.0f,34.2f},{6.0f,1.2f},{8.4f,-8.4f},{15.6f,-22.8f} };
        NODE_A = 27; NODE_B = 13;
        int ag[5] = { 27, 26, 28, 29, 25 }, bg[5] = { 13, 12, 14, 15, 11 };
        for (int i = 0; i < 5; i++) { A_GUARD[i] = ag[i]; B_GUARD[i] = bg[i]; }
    } else {
        NODE_A = 28; NODE_B = 20;
        int ag[5] = { 28, 29, 30, 27, 26 }, bg[5] = { 20, 21, 22, 19, 23 };
        for (int i = 0; i < 5; i++) { A_GUARD[i] = ag[i]; B_GUARD[i] = bg[i]; }
    gNodes = {
            {2.4f,52.3f},{-9.3f,52.3f},{-6.4f,40.6f},{5.3f,39.1f},
            {-4.9f,25.0f},{-4.9f,16.5f},{-4.9f,5.5f},{-4.9f,-6.2f},
            {-4.9f,-15.5f},{-21.0f,-18.6f},{-41.5f,-18.6f},{-40.0f,-6.2f},
            {-40.0f,9.4f},{-44.4f,27.4f},{-25.4f,40.6f},{14.1f,25.0f},
            {22.9f,9.4f},{38.7f,1.6f},{38.7f,-6.2f},{18.5f,-6.9f},
            {36.7f,-22.9f},{21.4f,-25.7f},{30.2f,-17.1f},{14.1f,-29.6f},
            {3.9f,-35.0f},{-3.4f,-40.5f},{-3.1f,-46.3f},{8.3f,-49.8f},
            {31.0f,-49.8f},{41.9f,-53.0f},{37.6f,-45.2f},{-23.9f,-50.6f},
            {-41.5f,-51.4f},{-41.5f,-37.4f},{-41.5f,-25.7f},{-23.9f,-45.2f},
            {34.6f,28.9f},{39.0f,9.4f}
        };
    }
    int n = (int)gNodes.size();
    gAdj.assign(n, vector<int>());
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++)
            if (Vector2Distance(gNodes[i], gNodes[j]) < (gMap >= 2 ? 9.0f : 46.0f) && SegClear(gNodes[i], gNodes[j], 0.7f)) {
                gAdj[i].push_back(j);
                gAdj[j].push_back(i);
            }
}
static int NearestNode(Vector2 p) {
    int best = 0, bestClear = -1;
    float bd = 1e9f, bdc = 1e9f;
    for (int i = 0; i < (int)gNodes.size(); i++) {
        float d = Vector2Distance(p, gNodes[i]);
        if (d < bd) { bd = d; best = i; }
        if (d < bdc && SegClear(p, gNodes[i], 0.3f)) { bdc = d; bestClear = i; }
    }
    return bestClear >= 0 ? bestClear : best;
}
static vector<int> NodePath(int s, int g) {
    int n = (int)gNodes.size();
    vector<float> dist(n, 1e9f);
    vector<int> prev(n, -1);
    vector<bool> done(n, false);
    dist[s] = 0.0f;
    for (int it = 0; it < n; it++) {
        int u = -1;
        for (int i = 0; i < n; i++) if (!done[i] && (u < 0 || dist[i] < dist[u])) u = i;
        if (u < 0 || dist[u] >= 1e9f) break;
        done[u] = true;
        for (int v : gAdj[u]) {
            float nd = dist[u] + Vector2Distance(gNodes[u], gNodes[v]);
            if (nd < dist[v]) { dist[v] = nd; prev[v] = u; }
        }
    }
    vector<int> p;
    if (dist[g] >= 1e9f) return p;
    for (int c = g; c != -1; c = prev[c]) p.push_back(c);
    std::reverse(p.begin(), p.end());
    return p;
}

