    bool hasGoalPos = false;
    float dvx = 0.0f, dvz = 0.0f, lvx = 0.0f, lvz = 0.0f, zLastX = 0.0f, zLastZ = 0.0f, zAcc = 0.0f;   // зоны карт: скольжение, запуск с площадки, лёд
